css:
.forensic-sim-container {
    padding: 28px;
    background: #0a1628;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #cbd5e1;
}
.forensic-sim-container * { box-sizing: border-box; }

.forensic-sim-header {
    border-left: 4px solid #00d9ff;
    padding: 22px 28px;
    margin-bottom: 28px;
    background: linear-gradient(90deg, rgba(0,217,255,0.08) 0%, rgba(0,217,255,0) 100%);
    border-top: 1px solid #1e3a5f;
    border-right: 1px solid #1e3a5f;
    border-bottom: 1px solid #1e3a5f;
    border-radius: 4px;
}
.forensic-sim-mark {
    color: #00d9ff;
    font-size: 0.7rem;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    margin-bottom: 10px;
    font-weight: 600;
}
.forensic-sim-header h1 {
    color: #f1f5f9;
    font-size: 1.6rem;
    font-weight: 700;
    margin: 0 0 6px 0;
    line-height: 1.25;
}
.forensic-sim-subtitle {
    color: #64748b;
    font-size: 0.85rem;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    margin-bottom: 16px;
}
.forensic-sim-counter {
    color: #94a3b8;
    font-size: 0.85rem;
    letter-spacing: 0.04em;
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
}
.forensic-sim-counter-tag {
    color: #00d9ff;
    text-transform: uppercase;
    font-weight: 600;
}
.forensic-sim-counter-num {
    color: #f1f5f9;
    font-weight: 700;
    font-size: 1rem;
}
.forensic-sim-divider { color: #1e3a5f; }
.forensic-sim-round-title {
    color: #00d9ff;
    text-transform: uppercase;
    font-weight: 600;
    letter-spacing: 0.08em;
}

.forensic-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 14px;
    margin-bottom: 28px;
}
.forensic-sim-kpi-card {
    background: #0f1f3a;
    border: 1px solid #1e3a5f;
    border-radius: 6px;
    padding: 18px 18px;
    position: relative;
    overflow: hidden;
    transition: transform 0.18s ease, border-color 0.18s ease;
}
.forensic-sim-kpi-card:hover {
    transform: translateY(-2px);
    border-color: #2d4f7f;
}
.forensic-sim-kpi-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 2px;
    background: #00d9ff;
}
.forensic-sim-kpi-card.kpi-custody::before { background: #22c55e; }
.forensic-sim-kpi-card.kpi-interview::before { background: #a855f7; }
.forensic-sim-kpi-card.kpi-cross::before { background: #f59e0b; }
.forensic-sim-kpi-card.kpi-pericial::before { background: linear-gradient(90deg, #00d9ff, #22c55e); }
.forensic-sim-kpi-card.kpi-damage::before { background: #ef4444; }

.forensic-sim-kpi-label {
    color: #64748b;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    margin-bottom: 10px;
    font-weight: 600;
}
.forensic-sim-kpi-value {
    font-size: 1.7rem;
    font-weight: 700;
    color: #f1f5f9;
    line-height: 1;
}
.kpi-detection .forensic-sim-kpi-value { color: #00d9ff; }
.kpi-custody .forensic-sim-kpi-value { color: #22c55e; }
.kpi-interview .forensic-sim-kpi-value { color: #a855f7; }
.kpi-cross .forensic-sim-kpi-value { color: #f59e0b; }
.kpi-pericial .forensic-sim-kpi-value { color: #f1f5f9; }
.kpi-damage .forensic-sim-kpi-value { color: #ef4444; font-size: 1.35rem; }

.forensic-sim-controls {
    background: #0f1f3a;
    border: 1px solid #1e3a5f;
    border-radius: 6px;
    padding: 26px 28px;
    margin-bottom: 28px;
}
.forensic-sim-controls-h {
    color: #00d9ff;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    margin: 0 0 22px 0;
    padding-bottom: 12px;
    border-bottom: 1px solid #1e3a5f;
    font-weight: 700;
}

.forensic-sim-panel { display: block; }
.forensic-sim-brief {
    background: rgba(0,217,255,0.05);
    border-left: 3px solid #00d9ff;
    color: #cbd5e1;
    padding: 14px 16px;
    border-radius: 0 4px 4px 0;
    margin-bottom: 22px;
    font-size: 0.92rem;
    line-height: 1.6;
}

.forensic-sim-section-label {
    color: #94a3b8;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    margin: 18px 0 10px 0;
    font-weight: 600;
}

.forensic-sim-checks {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 8px;
    margin-bottom: 12px;
}
.forensic-sim-check {
    display: flex;
    align-items: flex-start;
    gap: 10px;
    background: #081224;
    border: 1px solid #1e3a5f;
    border-radius: 4px;
    padding: 10px 12px;
    color: #e0e6f0;
    font-size: 0.88rem;
    cursor: pointer;
    margin: 0;
    transition: border-color 0.18s ease, background 0.18s ease;
}
.forensic-sim-check:hover {
    border-color: #00d9ff;
    background: #0a1830;
}
.forensic-sim-check input[type="checkbox"] {
    margin: 3px 0 0 0;
    accent-color: #00d9ff;
    cursor: pointer;
}
.forensic-sim-check span { line-height: 1.4; }
.forensic-sim-check-warn {
    border-color: #ef4444;
    background: rgba(239,68,68,0.08);
}
.forensic-sim-check-warn:hover {
    border-color: #f87171;
    background: rgba(239,68,68,0.14);
}
.forensic-sim-warn-note {
    color: #f87171;
    font-size: 0.78rem;
    margin: 6px 0 12px 0;
    font-style: italic;
}

.forensic-sim-select,
.forensic-sim-input {
    background: #081224;
    border: 1px solid #2d4f7f;
    color: #f1f5f9;
    border-radius: 4px;
    padding: 10px 12px;
    width: 100%;
    font-size: 0.92rem;
    font-family: inherit;
    margin-bottom: 8px;
    transition: border-color 0.18s ease;
}
.forensic-sim-select:focus,
.forensic-sim-input:focus {
    outline: none;
    border-color: #00d9ff;
    box-shadow: 0 0 0 2px rgba(0,217,255,0.18);
}
.forensic-sim-select option {
    background: #0f1f3a;
    color: #f1f5f9;
}

.forensic-sim-attack-block {
    background: #081224;
    border: 1px solid #1e3a5f;
    border-radius: 6px;
    padding: 16px 18px;
    margin-bottom: 16px;
}
.forensic-sim-quote {
    color: #f59e0b;
    font-style: italic;
    border-left: 3px solid #f59e0b;
    padding: 8px 12px;
    margin: 8px 0 12px 0;
    background: rgba(245,158,11,0.06);
    border-radius: 0 4px 4px 0;
    font-size: 0.9rem;
    line-height: 1.5;
}

.forensic-sim-actions {
    display: flex;
    gap: 12px;
    margin-top: 22px;
    flex-wrap: wrap;
}
.forensic-sim-submit {
    background: #00d9ff;
    color: #0a1628;
    border: none;
    padding: 12px 28px;
    border-radius: 4px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    font-size: 0.85rem;
    cursor: pointer;
    transition: background 0.18s ease, transform 0.12s ease;
}
.forensic-sim-submit:hover {
    background: #38e2ff;
    transform: translateY(-1px);
}
.forensic-sim-undo {
    background: transparent;
    color: #94a3b8;
    border: 1px solid #2d4f7f;
    padding: 12px 22px;
    border-radius: 4px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    font-size: 0.78rem;
    cursor: pointer;
    transition: border-color 0.18s ease, color 0.18s ease;
}
.forensic-sim-undo:hover {
    border-color: #00d9ff;
    color: #00d9ff;
}

.forensic-sim-section-header {
    color: #00d9ff;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    margin-bottom: 14px;
    font-weight: 700;
}

.forensic-sim-history {
    background: #0f1f3a;
    border: 1px solid #1e3a5f;
    border-radius: 6px;
    padding: 22px 24px;
    margin-bottom: 28px;
    overflow-x: auto;
}
.forensic-sim-table {
    width: 100%;
    color: #cbd5e1;
    font-size: 0.88rem;
    border-collapse: collapse;
}
.forensic-sim-table thead th {
    color: #94a3b8;
    text-transform: uppercase;
    font-size: 0.7rem;
    letter-spacing: 0.1em;
    font-weight: 600;
    border-bottom: 1px solid #1e3a5f;
    padding: 10px 12px;
    text-align: left;
}
.forensic-sim-table tbody td {
    padding: 10px 12px;
    border-bottom: 1px solid #14253f;
}
.forensic-sim-table tbody tr:hover {
    background: rgba(0,217,255,0.04);
}

.forensic-sim-chart-wrapper {
    background: #0f1f3a;
    border: 1px solid #1e3a5f;
    border-radius: 6px;
    padding: 22px 24px;
    margin-bottom: 28px;
}
.forensic-sim-chart {
    height: 360px;
    width: 100%;
    position: relative;
}

@media (max-width: 768px) {
    .forensic-sim-container { padding: 16px; }
    .forensic-sim-header { padding: 16px 18px; }
    .forensic-sim-header h1 { font-size: 1.2rem; }
    .forensic-sim-kpi-grid { grid-template-columns: repeat(2, 1fr); gap: 10px; }
    .forensic-sim-kpi-value { font-size: 1.4rem; }
    .forensic-sim-checks { grid-template-columns: 1fr; }
    .forensic-sim-controls { padding: 18px 16px; }
    .forensic-sim-actions { flex-direction: column; }
    .forensic-sim-submit, .forensic-sim-undo { width: 100%; }
    .forensic-sim-chart { height: 300px; }
}


/* --- EQIL additions (adapter 1.1.0) --- */
.forensic-sim-complete-banner {
    margin: 12px 0;
    padding: 12px 16px;
    border-radius: 4px;
    border: 1px solid #1a2744;
    background: #eef1f6;
    color: #1a2744;
    font-weight: 600;
}
button:focus-visible, select:focus-visible, input:focus-visible {
    outline: 3px solid #1a2744;
    outline-offset: 2px;
}
@media (prefers-reduced-motion: reduce) {
    .forensic-sim-shell * {
        animation-duration: 0.001ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.001ms !important;
        scroll-behavior: auto !important;
    }
}

/* EQIL 2026-11-13: AA contrast on the dark header and KPI labels */
.forensic-sim-container .forensic-sim-subtitle { color: #7386a0; }
.forensic-sim-container .forensic-sim-divider { color: #4b86d4; }
.forensic-sim-container .forensic-sim-kpi-label { color: #7386a0; }

