            return 'needs_work';
        }

        _syncControlsFromDecisions(state) {
            var d = (state && state.decisions) || {};
            Object.keys(d).forEach(function(k) {
                var el = document.getElementById(k);
                if (!el) return;
                var v = d[k];
                if (el.type === 'checkbox') el.checked = !!v;
                else if (v !== undefined && v !== null) el.value = String(v);
            });
        }

        _applyEndState(period) {
            var done = Number(period) > 4;
            var btn = document.getElementById('nextPeriodBtn');
            if (btn) { btn.disabled = done; btn.style.display = done ? 'none' : ''; }
            var banner = document.getElementById('runCompleteBanner');
            if (banner) {
                banner.style.display = done ? 'block' : 'none';
                if (done) banner.textContent = this._L(
                    'Run complete. Testimony is closed - review your pericial scores, chart and conclusion below.',
                    'Simulación completada. El testimonio está cerrado: revise abajo sus puntuaciones periciales, la gráfica y la conclusión.');
            }
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var score = (s.overallScore != null) ? s.overallScore : 0;
            var head = this._L('Pericial Verdict', 'Veredicto pericial');
            var lbl = {
                score: this._L('Overall pericial score', 'Puntuación pericial global'),
                det: this._L('Detection', 'Detección'),
                cus: this._L('Chain of custody', 'Cadena de custodia'),
                intv: this._L('Interview', 'Entrevista'),
                cx: this._L('Cross-examination', 'Contrainterrogatorio'),
                next: this._L('What to take away', 'Qué llevarse')
            };
            var n = function(v) { return v != null ? v : '-'; };
            var rows = ''
                + '<li><strong>' + lbl.score + ':</strong> ' + score + '/100 (' + (s.performanceLabel || s.performance || '') + ')</li>'
                + '<li><strong>' + lbl.det + ':</strong> ' + n(s.detectionScore) + '/100</li>'
                + '<li><strong>' + lbl.cus + ':</strong> ' + n(s.custodyScore) + '/100</li>'
                + '<li><strong>' + lbl.intv + ':</strong> ' + n(s.interviewScore) + '/100</li>'
                + '<li><strong>' + lbl.cx + ':</strong> ' + n(s.crossExamScore) + '/100</li>';
            var tips = (s.insights || []).map(function(x) { return '<li>' + x + '</li>'; }).join('');
            return '<div class="forensic-sim-complete"><h3>' + head + '</h3><ul>' + rows + '</ul>'
                 + '<h4>' + lbl.next + '</h4><ul>' + tips + '</ul></div>';
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    detectionScore: 0,
                    custodyScore: 0,
                    interviewScore: 0,
                    pericialScore: 0,
                    crossExamScore: 0,
                    overallScore: 0,
                    estimatedDamage: 0,
                    findings: [],
                    breaches: [],
                    detectionHistory: [],
                    custodyHistory: [],
                    interviewHistory: [],
                    crossExamHistory: [],
                    pericialHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {};
            }
            var self = this;
            this._bindRepaint();
            setTimeout(function() { self._updateBriefing(state); }, 50);
            setTimeout(function() {
                self._syncControlsFromDecisions(state);
                self._updateBriefing(state);
            }, 0);
        }

        _needsChoice(ids) {
            for (var i = 0; i < ids.length; i++) {
                if (!this._val(ids[i])) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_pick_option'), 'warning');
                    return true;
                }
            }
            return false;
        }

        validateDecisions(decisions) {
            var period = window.mySimulation.state.currentPeriod;
            this._updateBriefing(window.mySimulation.state);

            if (period === 1) {
                decisions.benford     = this._chk('chkBenford');
                decisions.vendorConc  = this._chk('chkVendorConc');
                decisions.threshold   = this._chk('chkThreshold');
                decisions.timing      = this._chk('chkTiming');
                decisions.conflict    = this._chk('chkConflict');
                decisions.gapAnalysis = this._chk('chkGapAnalysis');
                decisions.roundNum    = this._chk('chkRoundNum');
                decisions.hypothesis  = this._val('selHypothesis');
                decisions.estDamage   = parseFloat(this._val('estDamage')) || 0;

                // no minimum number of screens: an empty screen set scores zero screen points, as rounds 2 and 3 already allow
                if (this._needsChoice(['selHypothesis'])) return false;
            } else if (period === 2) {
                decisions.writeBlocker = this._chk('chkWriteBlocker');
                decisions.hashing      = this._chk('chkHashing');
                decisions.custodyForm  = this._chk('chkCustodyForm');
                decisions.videoDoc     = this._chk('chkVideoDoc');
                decisions.eDiscovery   = this._chk('chkEDiscovery');
                decisions.erpAudit     = this._chk('chkErpAudit');
                decisions.bankFiscalia = this._chk('chkBankFiscalia');
                decisions.accessLogs   = this._chk('chkAccessLogs');
                decisions.whatsapp     = this._chk('chkWhatsApp');
                decisions.adminLogin   = this._chk('chkAdminLogin');
            } else if (period === 3) {
                decisions.consent         = this._chk('chkConsent');
                decisions.defensorPresent = this._chk('chkDefensor');
                decisions.audioRecord     = this._chk('chkAudio');
                decisions.observer        = this._chk('chkObserver');
                decisions.avoidLeading    = this._chk('chkAvoidLeading');
                decisions.avoidCoercion   = this._chk('chkAvoidCoercion');
                decisions.protocol        = this._val('selProtocol');
                decisions.intGoal         = this._val('selIntGoal');
                if (this._needsChoice(['selProtocol', 'selIntGoal'])) return false;
            } else if (period === 4) {
                decisions.respCustody     = this._val('selRespCustody');
                decisions.respBenford     = this._val('selRespBenford');
                decisions.respParcialidad = this._val('selRespParcialidad');
                decisions.conclusionStyle = this._val('selConclStyle');
                if (this._needsChoice(['selRespCustody', 'selRespBenford', 'selRespParcialidad', 'selConclStyle'])) return false;
            }
            return true;
        }

        _chk(id) {
            var el = document.getElementById(id);
            return el ? !!el.checked : false;
        }
        _val(id) {
            var el = document.getElementById(id);
            return el ? el.value : '';
        }

        calculateResults(state) {
            var period = state.currentPeriod;
            var d = state.decisions;
            var ds = state.domainState;
            var roundScore = 0;
            var insights = [];
            var results = { period: period };

            if (period === 1) {
                var checks = [d.benford, d.vendorConc, d.threshold, d.timing,
                              d.conflict, d.gapAnalysis, d.roundNum];
                var checkedCount = checks.filter(function(c) { return c; }).length;
                roundScore = checkedCount * 12;

                if (d.hypothesis === 'dual')          roundScore += 16;
                else if (d.hypothesis === 'fraud_only')   { roundScore -= 10; insights.push('confirmation_bias'); this._breach(ds, 'predetermined'); }
                else if (d.hypothesis === 'control_only') { roundScore -= 10; insights.push('underclaim'); }

                if (d.estDamage >= 1500 && d.estDamage <= 3500) roundScore += 6;

                roundScore = Math.max(0, Math.min(100, roundScore));
                ds.detectionScore = roundScore;
                ds.detectionHistory.push(roundScore);
                ds.estimatedDamage = d.estDamage;

                if (d.benford)   ds.findings.push('benford_anomaly');
                if (d.timing)    ds.findings.push('timing_28_30');
                if (d.conflict)  ds.findings.push('cunado_link');
                if (d.threshold) ds.findings.push('threshold_proximity');
                if (d.gapAnalysis) ds.findings.push('service_gap');

                results.detectionScore = roundScore;
                results.estimatedDamage = d.estDamage;
                results.checksApplied = checkedCount;
                results.overallScore = Math.round(roundScore / 4);
                ds.overallScore = results.overallScore;
            } else if (period === 2) {
                var procs = [d.writeBlocker, d.hashing, d.custodyForm, d.videoDoc,
                             d.eDiscovery, d.erpAudit, d.bankFiscalia, d.accessLogs, d.whatsapp];
                var procCount = procs.filter(function(p) { return p; }).length;
                var imageHolds = !!d.writeBlocker && !d.adminLogin;
                var hashHolds  = !!d.hashing && !d.adminLogin;
                var credited = procCount - (d.writeBlocker && !imageHolds ? 1 : 0) - (d.hashing && !hashHolds ? 1 : 0);
                roundScore = Math.round(credited * 100 / 9);

                if (!imageHolds) { roundScore -= 20; insights.push('no_writeblocker'); }
                if (!hashHolds)  { roundScore -= 15; insights.push('no_hash'); }
                if (!d.custodyForm)  { roundScore -= 15; insights.push('no_custody_form'); }

                if (d.adminLogin) {
                    roundScore -= 35;
                    insights.push('admin_login_disaster');
                    this._breach(ds, 'live_login');
                }

                roundScore = Math.max(0, Math.min(100, roundScore));
                ds.custodyScore = roundScore;
                ds.custodyHistory.push(roundScore);

                results.custodyScore = roundScore;
                results.proceduresExecuted = procCount;
                results.overallScore = Math.round((ds.detectionScore + roundScore) / 4);
                ds.overallScore = results.overallScore;
            } else if (period === 3) {
                var protections = [d.consent, d.defensorPresent, d.audioRecord,
                                   d.observer, d.avoidLeading, d.avoidCoercion];
                var protCount = protections.filter(function(p) { return p; }).length;
                roundScore = protCount * 10;

                if (d.protocol === 'fisher_geiselman') roundScore += 25;
                else if (d.protocol === 'pace')        roundScore += 5;
                else if (d.protocol === 'reid')        { roundScore -= 15; insights.push('reid_risk'); }

                if (d.intGoal === 'verifiable_admissions') roundScore += 15;
                else if (d.intGoal === 'confession')       { roundScore -= 10; insights.push('confession_seeking'); this._breach(ds, 'confession'); }

                if (!d.defensorPresent) { roundScore -= 25; insights.push('no_defensor'); }
                if (!d.consent)         { roundScore -= 20; insights.push('no_consent'); }

                roundScore = Math.max(0, Math.min(100, roundScore));
                ds.interviewScore = roundScore;
                ds.interviewHistory.push(roundScore);

                results.interviewScore = roundScore;
                results.overallScore = Math.round((ds.detectionScore + ds.custodyScore + roundScore) / 4);
                ds.overallScore = results.overallScore;
            } else if (period === 4) {
                var pts = 25;

                if (d.respCustody === 'log_minute_by_minute')   pts += 25;
                else if (d.respCustody === 'general_assurance') pts += 0;
                else if (d.respCustody === 'deflect_objection') { pts -= 10; insights.push('weak_custody_response'); }

                if (d.respBenford === 'screen_not_proof')     pts += 25;
                else if (d.respBenford === 'defend_as_proof') { pts -= 15; insights.push('benford_overclaim'); this._breach(ds, 'screen_as_proof'); }
                else if (d.respBenford === 'avoid_question')  { pts -= 8;  insights.push('benford_evade'); }

                if (d.respParcialidad === 'fixed_fees_disclose') pts += 25;
                else if (d.respParcialidad === 'minimize')       { pts -= 8;  insights.push('parcialidad_minimize'); }
                else if (d.respParcialidad === 'evade')          { pts -= 15; insights.push('parcialidad_evade'); }

                if (d.conclusionStyle === 'tecnico_contable')   pts += 0;
                else if (d.conclusionStyle === 'juridical')     { pts -= 20; insights.push('over_claim'); this._breach(ds, 'legal_classification'); }

                // the defence cashes in every earlier act that got ahead of the evidence
                pts -= this.BREACH_COST * (ds.breaches || []).length;
                roundScore = Math.max(0, Math.min(100, pts));
                ds.crossExamScore = roundScore;
                ds.crossExamHistory.push(roundScore);

                ds.pericialScore = this._composite(ds);
                ds.pericialHistory.push(ds.pericialScore);

                results.crossExamScore = roundScore;
                results.pericialScore = ds.pericialScore;
                results.overallScore = ds.pericialScore;
                ds.overallScore = ds.pericialScore;
            }

            results.insights = insights;
            ds.performance = { overallScore: results.overallScore };

            return results;
        }

        _bindRepaint() {
            if (this._repaintBound) return;
            this._repaintBound = true;
            var self = this;
            var repaint = function() {
                var sim = window.mySimulation;
                if (sim && sim.state) self._updateBriefing(sim.state);
            };
            document.addEventListener('express:langchanged', repaint);
            var bus = window.mySimulation && window.mySimulation.eventBus;
            if (bus && typeof bus.on === 'function') {
                ['period:submitted', 'period:undone', 'state:loaded', 'language:changed', 'simulation:reset'].forEach(function(ev) {
                    bus.on(ev, repaint);
                });
            }
        }

        _updateBriefing(state) {
            var period = (state && state.currentPeriod) || 1;
            var hist = (state && Array.isArray(state.history)) ? state.history.length : 0;
            if (hist >= this.ROUNDS.length) period = this.ROUNDS.length + 1;
            this._applyEndState(period);
            var idx = Math.max(0, Math.min(period - 1, this.ROUNDS.length - 1));

            for (var i = 0; i < this.ROUNDS.length; i++) {
                var el = document.getElementById(this.ROUNDS[i].panel);
                if (el) el.style.display = (i === idx) ? 'block' : 'none';
            }

            var titleEl = document.getElementById('roundTitle');
            if (titleEl && window.mySimulation && window.mySimulation.t) {
                titleEl.textContent = window.mySimulation.t(this.ROUNDS[idx].titleKey);
            }
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('detectionScoreDisplay', 'domainState.detectionScore', (v) => v + ' / 100');
            uiManager.bind('custodyScoreDisplay',   'domainState.custodyScore',   (v) => v + ' / 100');
            uiManager.bind('interviewScoreDisplay', 'domainState.interviewScore', (v) => v + ' / 100');
            uiManager.bind('crossExamScoreDisplay', 'domainState.crossExamScore', (v) => v + ' / 100');
            uiManager.bind('pericialScoreDisplay',  'domainState.pericialScore',  (v) => v + ' / 100');
            uiManager.bind('damageDisplay',         'domainState.estimatedDamage',
                (v) => 'COP ' + Math.round(v).toLocaleString() + ' M');
        }

