        getChartData(state) {
            var ds = (state && state.domainState) || {};
            var num = function(x) { return Number(x) || 0; };
            return {
                metricsChart: {
                    labels: [
                        this._L('Detection', 'Detección'),
                        this._L('Custody', 'Custodia'),
                        this._L('Interview', 'Entrevista'),
                        this._L('Cross-Exam', 'Contrainterrogatorio'),
                        this._L('Pericial', 'Pericial')
                    ],
                    datasets: [{
                        data: [
                            num(ds.detectionScore),
                            num(ds.custodyScore),
                            num(ds.interviewScore),
                            num(ds.crossExamScore),
                            num(ds.pericialScore)
                        ]
                    }]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var ds = window.mySimulation.state.domainState;
            var composite = this._composite(ds);
            var pericial = composite;
            var perf = this._band(composite);
            var perfLabels = {
                excellent:  this._L('Excellent', 'Excelente'),
                good:       this._L('Good', 'Bueno'),
                developing: this._L('Developing', 'En desarrollo'),
                needs_work: this._L('Needs work', 'Necesita trabajo')
            };

            var insights = [];
            var t = window.mySimulation.t.bind(window.mySimulation);
            (ds.breaches || []).forEach(function(b) { insights.push(t('debrief_' + b)); });
            if (ds.detectionScore < 60) insights.push(window.mySimulation.t('insight_low_detection'));
            if (ds.custodyScore   < 60) insights.push(window.mySimulation.t('insight_low_custody'));
            if (ds.interviewScore < 60) insights.push(window.mySimulation.t('insight_low_interview'));
            if (ds.crossExamScore < 60) insights.push(window.mySimulation.t('insight_low_cross'));
            if (pericial >= 80)         insights.push(window.mySimulation.t('insight_high_overall'));

            return {
                detectionScore: ds.detectionScore,
                custodyScore:   ds.custodyScore,
                interviewScore: ds.interviewScore,
                crossExamScore: ds.crossExamScore,
                pericialScore:  pericial,
                composite:      composite,
                overallScore:   composite,
                totalScore:     composite,
                score:          composite,
                performance:    perf,
                performanceKey: perf,
                performanceLabel: perfLabels[perf],
                insights:       insights
            };
        }

        getHint(state, results) {
            if (!results || !results.insights) return null;
            var ins = results.insights;
            if (ins.indexOf('admin_login_disaster') >= 0) return window.mySimulation.t('hint_admin_login');
            if (ins.indexOf('confirmation_bias') >= 0)    return window.mySimulation.t('hint_confirmation_bias');
            if (ins.indexOf('over_claim') >= 0)           return window.mySimulation.t('hint_over_claim');
            if (ins.indexOf('confession_seeking') >= 0)   return window.mySimulation.t('hint_confession_seeking');
            if (ins.indexOf('no_defensor') >= 0)          return window.mySimulation.t('hint_no_defensor');
            if (ins.indexOf('benford_overclaim') >= 0)    return window.mySimulation.t('hint_benford_overclaim');
            if (ins.indexOf('reid_risk') >= 0)            return window.mySimulation.t('hint_reid_risk');
            if (results.detectionScore !== undefined && results.detectionScore < 60)
                return window.mySimulation.t('hint_low_detection');
            if (results.custodyScore !== undefined && results.custodyScore < 60)
                return window.mySimulation.t('hint_low_custody');
            return null;
        }

